import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";

/** A request to retrieve a gift card by using a payment token. */
export type RetrieveGiftCardFromNonceRequest = {
  /**
   * The payment token of the gift card to retrieve. Payment tokens are generated by the Web
   * Payments SDK or In-App Payments SDK.
   */
  nonce: string;
};

export const retrieveGiftCardFromNonceRequestSchema: Schema<RetrieveGiftCardFromNonceRequest> =
  s.object<RetrieveGiftCardFromNonceRequest>({
    nonce: s.string(),
  });
